create extension if not exists pgcrypto;
create type public.app_role as enum ('customer','admin');
create type public.order_state as enum ('pending_payment','paid','confirmed','preparing','ready','out_for_delivery','delivered','cancelled','refunded');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',phone text,role public.app_role not null default 'customer',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.addresses(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,label text,address text not null,city text not null,state text not null,landmark text,created_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,description text,image_url text,sort_order int not null default 0,active boolean not null default true,created_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id),name text not null,slug text not null unique,description text not null default '',active boolean not null default false,featured boolean not null default false,lead_days int not null default 2 check(lead_days between 0 and 60),customization jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.product_images(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,storage_path text not null,alt text not null default '',sort_order int not null default 0);
create table public.product_variants(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,name text not null,price_kobo bigint not null check(price_kobo>=0),active boolean not null default true,unique(product_id,name));
create table public.customizations(id uuid primary key default gen_random_uuid(),product_id uuid not null references public.products(id) on delete cascade,kind text not null check(kind in ('flavour','colour','addon')),label text not null,options jsonb not null default '[]'::jsonb,fee_kobo bigint not null default 0 check(fee_kobo>=0),active boolean not null default true);
create table public.delivery_zones(id uuid primary key default gen_random_uuid(),state text not null,city text not null,charge_kobo bigint not null check(charge_kobo>=0),active boolean not null default true,unique(state,city));
create table public.delivery_slots(id uuid primary key default gen_random_uuid(),zone_id uuid references public.delivery_zones(id) on delete cascade,window_name text not null,weekday smallint check(weekday between 0 and 6),cutoff_time time,active boolean not null default true);
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text not null unique default ('SC-'||upper(substr(encode(gen_random_bytes(8),'hex'),1,10))),user_id uuid references public.profiles(id),customer_name text not null,customer_email text not null,customer_email_norm text generated always as(lower(customer_email)) stored,customer_phone text not null,delivery_address text not null,city text not null,state text not null,landmark text not null default '',delivery_instructions text not null default '',delivery_zone_id uuid references public.delivery_zones(id),delivery_date date not null,delivery_window text not null,delivery_charge_kobo bigint not null default 0 check(delivery_charge_kobo>=0),subtotal_kobo bigint not null check(subtotal_kobo>=0),total_kobo bigint not null check(total_kobo>=0),status public.order_state not null default 'pending_payment',payment_status text not null default 'pending' check(payment_status in ('pending','success','failed','refunded')),admin_notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index orders_email_idx on public.orders(customer_email_norm); create index orders_created_idx on public.orders(created_at desc); create index products_category_idx on public.products(category_id,active);
create table public.order_items(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_snapshot jsonb not null,variant_snapshot jsonb not null,customization jsonb not null default '{}',quantity int not null check(quantity between 1 and 30),line_total_kobo bigint not null check(line_total_kobo>=0));
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id),reference text not null unique,transaction_id text,amount_kobo bigint not null check(amount_kobo>=0),currency text not null default 'NGN' check(currency='NGN'),status text not null default 'pending' check(status in ('pending','success','failed','refunded')),verified_at timestamptz,refund_reference text,created_at timestamptz not null default now());
create table public.order_status_history(id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,status public.order_state not null,note text,actor_id uuid references public.profiles(id),created_at timestamptz not null default now());
create table public.notifications(id uuid primary key default gen_random_uuid(),user_id uuid references public.profiles(id) on delete cascade,order_id uuid references public.orders(id) on delete cascade,channel text not null default 'in_app',title text not null,body text not null,read_at timestamptz,created_at timestamptz not null default now());
create table public.audit_log(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id),action text not null,entity text not null,entity_id uuid,details jsonb not null default '{}',created_at timestamptz not null default now());
create table public.reviews(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id),product_id uuid not null references public.products(id),order_id uuid not null references public.orders(id),rating int not null check(rating between 1 and 5),body text not null default '',approved boolean not null default false,created_at timestamptz not null default now(),unique(user_id,product_id,order_id));
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and role='admin') $$;
create or replace function public.create_speedcake_order(customer_name text,email text,phone text,address text,city text,state text,landmark text,instructions text,delivery_date date,delivery_window text,zone_id uuid,delivery_charge_kobo bigint,total_kobo bigint,items jsonb) returns public.orders language plpgsql security definer set search_path=public as $$ declare o public.orders; calculated bigint:=0; line jsonb; begin if jsonb_array_length(items)<1 or jsonb_array_length(items)>30 then raise exception 'Invalid item count'; end if; for line in select * from jsonb_array_elements(items) loop calculated:=calculated+(line->>'line_total_kobo')::bigint; end loop; if calculated+delivery_charge_kobo<>total_kobo then raise exception 'Total mismatch'; end if; if not exists(select 1 from delivery_zones where id=zone_id and active) then raise exception 'Delivery zone unavailable'; end if; insert into orders(user_id,customer_name,customer_email,customer_phone,delivery_address,city,state,landmark,delivery_instructions,delivery_zone_id,delivery_date,delivery_window,delivery_charge_kobo,subtotal_kobo,total_kobo) values(auth.uid(),customer_name,email,phone,address,city,state,landmark,instructions,zone_id,delivery_date,delivery_window,delivery_charge_kobo,calculated,total_kobo) returning * into o; for line in select * from jsonb_array_elements(items) loop insert into order_items(order_id,product_id,product_snapshot,variant_snapshot,customization,quantity,line_total_kobo) values(o.id,(line->>'product_id')::uuid,line->'product_snapshot',line->'variant_snapshot',coalesce(line->'customization','{}'),(line->>'quantity')::int,(line->>'line_total_kobo')::bigint); end loop; insert into order_status_history(order_id,status,note) values(o.id,'pending_payment','Order placed'); return o; end $$;
create or replace function public.confirm_speedcake_payment(payment_id uuid,transaction_id text) returns void language plpgsql security definer set search_path=public as $$ declare p payments; begin select * into p from payments where id=payment_id for update; if not found or p.status='success' then return; end if; update payments set status='success',transaction_id=confirm_speedcake_payment.transaction_id,verified_at=now() where id=p.id; update orders set payment_status='success',status='paid',updated_at=now() where id=p.order_id and status='pending_payment'; insert into order_status_history(order_id,status,note) values(p.order_id,'paid','Payment verified'); end $$;
create or replace function public.set_order_status(target_order uuid,next_status public.order_state,note_text text default null) returns void language plpgsql security definer set search_path=public as $$ declare current_status order_state; allowed boolean:=false; begin if not is_admin() then raise exception 'Forbidden'; end if; select status into current_status from orders where id=target_order for update; if current_status is null then raise exception 'Order not found'; end if; allowed:=case current_status when 'paid' then next_status in ('confirmed','cancelled','refunded') when 'confirmed' then next_status in ('preparing','cancelled') when 'preparing' then next_status in ('ready','cancelled') when 'ready' then next_status in ('out_for_delivery','cancelled') when 'out_for_delivery' then next_status='delivered' else false end; if not allowed then raise exception 'Invalid order status transition'; end if; update orders set status=next_status,updated_at=now() where id=target_order; insert into order_status_history(order_id,status,note,actor_id) values(target_order,next_status,note_text,auth.uid()); insert into audit_log(actor_id,action,entity,entity_id,details) values(auth.uid(),'order.status.update','orders',target_order,jsonb_build_object('from',current_status,'to',next_status,'note',note_text)); end $$;
alter table public.profiles enable row level security; alter table public.addresses enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_images enable row level security; alter table public.product_variants enable row level security; alter table public.customizations enable row level security; alter table public.delivery_zones enable row level security; alter table public.delivery_slots enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payments enable row level security; alter table public.order_status_history enable row level security; alter table public.notifications enable row level security; alter table public.audit_log enable row level security; alter table public.reviews enable row level security;
create policy profiles_self_read on profiles for select using(id=auth.uid() or is_admin()); create policy profiles_self_update on profiles for update using(id=auth.uid()) with check(id=auth.uid() and role=(select p.role from profiles p where p.id=auth.uid()));
create policy address_owner on addresses for all using(user_id=auth.uid() or is_admin()) with check(user_id=auth.uid() or is_admin());
create policy categories_public on categories for select using(active or is_admin()); create policy categories_admin on categories for all using(is_admin()) with check(is_admin());
create policy products_public on products for select using(active or is_admin()); create policy products_admin on products for all using(is_admin()) with check(is_admin());
create policy images_public on product_images for select using(exists(select 1 from products p where p.id=product_id and p.active) or is_admin()); create policy images_admin on product_images for all using(is_admin()) with check(is_admin());
create policy variants_public on product_variants for select using(active and exists(select 1 from products p where p.id=product_id and p.active) or is_admin()); create policy variants_admin on product_variants for all using(is_admin()) with check(is_admin());
create policy customizations_public on customizations for select using(active and exists(select 1 from products p where p.id=product_id and p.active) or is_admin()); create policy customizations_admin on customizations for all using(is_admin()) with check(is_admin());
create policy zones_public on delivery_zones for select using(active or is_admin()); create policy zones_admin on delivery_zones for all using(is_admin()) with check(is_admin()); create policy slots_public on delivery_slots for select using(active or is_admin()); create policy slots_admin on delivery_slots for all using(is_admin()) with check(is_admin());
create policy orders_owner_read on orders for select using(user_id=auth.uid() or is_admin()); create policy orders_admin_update on orders for update using(is_admin()) with check(is_admin());
create policy items_owner_read on order_items for select using(exists(select 1 from orders o where o.id=order_id and (o.user_id=auth.uid() or is_admin()))); create policy items_admin_all on order_items for all using(is_admin()) with check(is_admin());
create policy payments_owner_read on payments for select using(exists(select 1 from orders o where o.id=order_id and (o.user_id=auth.uid() or is_admin()))); create policy payments_admin_all on payments for all using(is_admin()) with check(is_admin());
create policy history_owner_read on order_status_history for select using(exists(select 1 from orders o where o.id=order_id and (o.user_id=auth.uid() or is_admin()))); create policy history_admin_all on order_status_history for all using(is_admin()) with check(is_admin());
create policy notifications_owner on notifications for select using(user_id=auth.uid() or is_admin()); create policy notifications_update on notifications for update using(user_id=auth.uid()) with check(user_id=auth.uid());
create policy audit_admin_read on audit_log for select using(is_admin()); create policy reviews_public on reviews for select using(approved); create policy reviews_owner_insert on reviews for insert with check(user_id=auth.uid() and exists(select 1 from orders o where o.id=order_id and o.user_id=auth.uid() and o.status='delivered'));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')); return new; end $$;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('product-images','product-images',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
create policy product_images_public_read on storage.objects for select using(bucket_id='product-images'); create policy product_images_admin_write on storage.objects for all using(bucket_id='product-images' and public.is_admin()) with check(bucket_id='product-images' and public.is_admin());
-- These RPCs are invoked only by the server using the service role. Anonymous
-- clients must not be able to forge snapshots or payment confirmation.
revoke all on function public.create_speedcake_order(text,text,text,text,text,text,text,text,date,text,uuid,bigint,bigint,jsonb) from public, anon, authenticated;
grant execute on function public.create_speedcake_order(text,text,text,text,text,text,text,text,date,text,uuid,bigint,bigint,jsonb) to service_role;
revoke all on function public.confirm_speedcake_payment(uuid,text) from public, anon, authenticated;
grant execute on function public.confirm_speedcake_payment(uuid,text) to service_role;
revoke all on function public.set_order_status(uuid,public.order_state,text) from public, anon;
grant execute on function public.set_order_status(uuid,public.order_state,text) to authenticated, service_role;
